class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def addTwoNumbers(self, l1, l2):
        def to_int(node):
            value, place = 0, 1
            while node:
                value += node.val * place
                place *= 10
                node = node.next
            return value

        total = to_int(l1) + to_int(l2)
        dummy = ListNode()
        tail = dummy
        if total == 0:
            return ListNode(0)
        while total:
            total, digit = divmod(total, 10)
            tail.next = ListNode(digit)
            tail = tail.next
        return dummy.next

