class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def addTwoNumbers(self, l1, l2):
        a, b = [], []
        while l1:
            a.append(l1.val)
            l1 = l1.next
        while l2:
            b.append(l2.val)
            l2 = l2.next

        dummy = ListNode()
        tail = dummy
        carry = i = 0
        while i < len(a) or i < len(b) or carry:
            total = carry
            if i < len(a):
                total += a[i]
            if i < len(b):
                total += b[i]
            carry, digit = divmod(total, 10)
            tail.next = ListNode(digit)
            tail = tail.next
            i += 1
        return dummy.next

